-- Ejecuta UNA VEZ si ya usabas la versión anterior. Conserva los viajes existentes.
create table if not exists public.centres (id uuid primary key default gen_random_uuid(), name text not null, country text not null, search_name text not null, source_url text, updated_at timestamptz not null default now(), unique(name,country));
create table if not exists public.courses (id uuid primary key default gen_random_uuid(), centre_id uuid not null references public.centres(id), course_type text not null, start_date date not null, end_date date not null check(end_date >= start_date), created_at timestamptz not null default now(), unique(centre_id,course_type,start_date,end_date));
alter table public.viajes add column if not exists course_id uuid references public.courses(id);
insert into public.centres(name,country,search_name) select distinct centro,'País sin especificar',lower(translate(centro,'áéíóúüÁÉÍÓÚÜ','aeiouuAEIOUU')) from public.viajes where centro is not null on conflict(name,country) do nothing;
insert into public.courses(centre_id,course_type,start_date,end_date) select c.id,coalesce(v.tipo_curso,'Curso sin especificar'),v.inicio_curso,v.fin_curso from public.viajes v join public.centres c on c.name=v.centro and c.country='País sin especificar' where v.course_id is null on conflict do nothing;
update public.viajes v set course_id=c.id from public.courses c join public.centres ce on ce.id=c.centre_id where v.course_id is null and ce.name=v.centro and c.course_type=coalesce(v.tipo_curso,'Curso sin especificar') and c.start_date=v.inicio_curso and c.end_date=v.fin_curso;
alter table public.centres enable row level security; alter table public.courses enable row level security; create policy "Centres visibles" on public.centres for select using (true); create policy "Cursos visibles" on public.courses for select using (true); create policy "Cursos públicos" on public.courses for insert with check (true);
